function longestCableRun(edges: number[][]): number {
  const n = edges.length + 1;
  if (n === 1) return 0;
  const adj: number[][] = Array.from({ length: n }, () => []);
  const deg = new Array(n).fill(0);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); deg[a]++; deg[b]++; }
  let layer: number[] = [];
  for (let i = 0; i < n; i++) if (deg[i] === 1) layer.push(i);
  let left = n, rounds = 0;
  while (left > 2) {
    left -= layer.length;
    rounds++;
    const next: number[] = [];
    for (const u of layer) for (const v of adj[u]) if (--deg[v] === 1) next.push(v);
    layer = next;
  }
  return 2 * rounds + (left === 2 ? 1 : 0);
}

