class Solution:
    def longestCableRun(self, edges: List[List[int]]) -> int:
        n = len(edges) + 1
        if n == 1:
            return 0
        adj = [[] for _ in range(n)]
        deg = [0] * n
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
            deg[a] += 1
            deg[b] += 1
        layer = [i for i in range(n) if deg[i] == 1]
        left, rounds = n, 0
        while left > 2:
            left -= len(layer)
            rounds += 1
            nxt = []
            for u in layer:
                for v in adj[u]:
                    deg[v] -= 1
                    if deg[v] == 1:
                        nxt.append(v)
            layer = nxt
        return 2 * rounds + (1 if left == 2 else 0)

